function mostrarModalToken(tokenId,token){const modal=document.getElementById("modal-token"),tokenDisplay=document.getElementById("token-display"),tokenValue=document.getElementById("token-value");tokenDisplay&&(tokenDisplay.textContent=tokenId);tokenValue&&(tokenValue.textContent=token);modal&&(modal.style.display="flex")}function cerrarModal(){const modal=document.getElementById("modal-token");modal&&(modal.style.display="none")}function copiarToken(){const tokenValue=document.getElementById("token-value");if(tokenValue){const tokenText=tokenValue.textContent;navigator.clipboard.writeText(tokenText).then(()=>{alert("Token copiado al portapapeles")}).catch(err=>{console.error("Error al copiar:",err)})}}function confirmarRevocacion(tipo){let mensaje="";switch(tipo){case"token1":mensaje="¿Estás seguro de revocar el RefreshToken1?\n\nEste token dejará de ser válido inmediatamente.";break;case"token2":mensaje="¿Estás seguro de revocar el RefreshToken2?\n\nEste token dejará de ser válido inmediatamente.";break;case"todos":mensaje="¿Estás seguro de revocar TODOS los tokens?\n\nEsto incluye:\n- RefreshToken1\n- RefreshToken2\n- AccessToken activo\n\nTodos los tokens dejarán de ser válidos inmediatamente."}return confirm(mensaje)}window.onclick=function(event){const modal=document.getElementById("modal-token");modal&&event.target===modal&&cerrarModal()};